    distinguish:
      "苏德罗森岭与蒂韦登都是瑞典南部的隆起丘陵地貌，但苏德罗森岭是断块构造抬升形成、两侧断崖陡立，蒂韦登则以冰川搬运的巨砾地貌为特征。",
    concept:
      "苏德罗森岭断块构造抬升形成的陡峭崖壁，是研究瑞典南部相对平坦的地质背景中局部构造断裂如何形成显著地形起伏的典型样本。",
